var metricsAggregator = require("../lib/MetricsAggregator");
const constants = require("./constants"); // No I18N

describe("Metrics Aggregator Super Class", () => {
  var gcMetricsAggs = new metricsAggregator();

  beforeEach(() => {
    gcMetricsAggs = new metricsAggregator();
    //aggregating stats
    gcMetricsAggs.addToExistingMetricData(constants.GC_STATS[0]);
    gcMetricsAggs.addToExistingMetricData(constants.GC_STATS[3]);
  }, 1);

  //Testing member method types
  test("defines addToExistingMetricData()", () => {
    expect(typeof gcMetricsAggs.addToExistingMetricData).toBe("function");
  });
  test("defines reset()", () => {
    expect(typeof gcMetricsAggs.reset).toBe("function");
  });
  test("defines getAsJson()", () => {
    expect(typeof gcMetricsAggs.getAsJson).toBe("function");
  });

  //Testing return types of each method
  test("addToExistingMetricData() returns undefined when called", () => {
    expect(
      gcMetricsAggs.addToExistingMetricData(constants.GC_STATS[0])
    ).toBeUndefined();
  });
  test("reset() returns undefined when called", () => {
    expect(gcMetricsAggs.reset()).toBeUndefined();
  });
  test("getAsJson() returns value when called", () => {
    expect(gcMetricsAggs.getAsJson()).toBeTruthy();
  });

  //Aggregation logic test
  test("addToExistingMetricData logic", () => {
    expect(gcMetricsAggs.count).toBe(
      constants.GC_STATS_AGGREGATED_VALUE[0].count
    );
  });

  test("addToExistingMetricData logic for eventloop stats", () => {
    gcMetricsAggs = new metricsAggregator();
    //aggregating stats
    gcMetricsAggs.addToExistingMetricData(constants.EVENT_LOOP_STATS[0]);
    gcMetricsAggs.addToExistingMetricData(constants.EVENT_LOOP_STATS[1]);
    expect(gcMetricsAggs.count).toBe(
      constants.EVENT_LOOP_STATS[0].num + constants.EVENT_LOOP_STATS[1].num
    );
  });

  test("getAsJson logic", () => {
    expect(gcMetricsAggs.getAsJson()).toStrictEqual(
      constants.METRICS_AGGREGATED_VALUE
    );
  });
});
